-- Phase N hardening: activate the orchestrator boundary, seed execution permission and make worker RPCs service-role safe.
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select id,'orchestration.execute',true,false from public.agents where agent_key in ('orchestrator','research','verification','knowledge-acquisition','curator','report','notification','security','optimization','module') on conflict(agent_id,permission) do update set allowed=excluded.allowed,requires_approval=excluded.requires_approval;
update public.agents set status='enabled',updated_at=now() where agent_key='orchestrator' and status='disabled';
create or replace function public.create_phase_n_orchestration_plan(p_task_id uuid,p_owner_id uuid,p_objective text,p_context jsonb,p_idempotency_key text,p_steps jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare t public.tasks;p public.orchestration_plans;existing jsonb;s jsonb;v_step public.orchestration_steps;seq integer:=0;sid text;akey text;deps jsonb;svc boolean:=coalesce(auth.role(),'')='service_role';begin if not svc and auth.uid() is distinct from p_owner_id then raise exception 'Forbidden: owner mismatch';end if;select * into t from public.tasks where id=p_task_id for update;if not found or t.owner_id<>p_owner_id then raise exception 'Task not found or not owned';end if;select to_jsonb(op) into existing from public.orchestration_plans op where op.task_id=p_task_id and op.owner_id=p_owner_id and op.intent=trim(p_objective) and op.status not in ('failed','cancelled','superseded') order by op.version desc limit 1;if existing is not null then return existing;end if;insert into public.orchestration_plans(task_id,owner_id,title,intent,capabilities,context,agents,expected_outputs,risk_level,status,version) values(p_task_id,p_owner_id,trim(p_objective),trim(p_objective),'["multi_agent_orchestration"]'::jsonb,coalesce(p_context,'{}'::jsonb),(select coalesce(jsonb_agg(distinct x->>'agentKey'),'[]') from jsonb_array_elements(p_steps) x),(select coalesce(jsonb_agg(distinct x->>'title'),'[]') from jsonb_array_elements(p_steps) x),'low','validated',1) returning * into p;for s in select value from jsonb_array_elements(p_steps) loop seq:=seq+1;sid=trim(coalesce(s->>'stepId',''));akey=trim(coalesce(s->>'agentKey',''));deps=coalesce(s->'dependsOn','[]'::jsonb);if sid='' or akey='' then raise exception 'Invalid orchestration step';end if;if akey='orchestrator' then raise exception 'Orchestrator cannot delegate to itself';end if;if not exists(select 1 from public.agents where agent_key=akey and status='enabled') then raise exception 'Agent is unavailable: %',akey;end if;insert into public.orchestration_steps(plan_id,task_id,sequence,step_key,kind,title,dependencies,agent_key,input_refs,expected_output,approval_required,status) values(p.id,p_task_id,seq,sid,'agent',coalesce(nullif(trim(s->>'title'),''),sid),'{}',akey,coalesce(s->'input','{}'::jsonb),jsonb_build_object('agent',akey),coalesce((s->>'requiresApproval')::boolean,false),case when jsonb_array_length(deps)=0 then 'ready' else 'pending' end) returning * into v_step;insert into public.orchestration_step_runtime(plan_id,orchestration_step_id,step_key,sequence,agent_key,depends_on_keys,requires_approval,requires_verification,max_retries,timeout_ms,critical) values(p.id,v_step.id,sid,seq,akey,deps,coalesce((s->>'requiresApproval')::boolean,false),coalesce((s->>'requiresVerification')::boolean,false),coalesce((s->>'maxRetries')::integer,2),coalesce((s->>'timeoutMs')::bigint,300000),coalesce((s->>'critical')::boolean,false));end loop;return to_jsonb(p);end;$$;
create or replace function public.claim_phase_n_step(p_runtime_step_id uuid,p_actor_id uuid) returns public.orchestration_step_runtime language plpgsql security definer set search_path=public as $$declare s public.orchestration_step_runtime;p public.orchestration_plans;svc boolean:=coalesce(auth.role(),'')='service_role';begin if not svc and auth.uid() is distinct from p_actor_id and not public.has_role(p_actor_id,'admin') then raise exception 'Forbidden';end if;select * into s from public.orchestration_step_runtime where id=p_runtime_step_id for update;if not found then raise exception 'Step not found';end if;select * into p from public.orchestration_plans where id=s.plan_id;if p.owner_id<>p_actor_id and not public.has_role(p_actor_id,'admin') and not svc then raise exception 'Forbidden';end if;if s.status not in ('pending','ready') then raise exception 'Step is not dispatchable';end if;if exists(select 1 from jsonb_array_elements_text(s.depends_on_keys) d where not exists(select 1 from public.orchestration_step_runtime x where x.plan_id=s.plan_id and x.step_key=d and x.status='completed')) then raise exception 'Step dependencies are not complete';end if;update public.orchestration_step_runtime set status='running',worker_id=p_actor_id::text,lease_expires_at=now()+interval '10 minutes',started_at=coalesce(started_at,now()),updated_at=now() where id=s.id returning * into s;update public.orchestration_steps set status='running',started_at=coalesce(started_at,now()) where id=s.orchestration_step_id;update public.orchestration_plans set status='executing',updated_at=now() where id=s.plan_id and status in ('draft','validated');return s;end;$$;
create or replace function public.complete_phase_n_step(p_runtime_step_id uuid,p_status text,p_result jsonb,p_warnings jsonb,p_errors jsonb,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare s public.orchestration_step_runtime;p public.orchestration_plans;total integer;done integer;failed integer;svc boolean:=coalesce(auth.role(),'')='service_role';begin if not svc and auth.uid() is distinct from p_actor_id and not public.has_role(p_actor_id,'admin') then raise exception 'Forbidden';end if;if p_status not in ('completed','failed','waiting_approval','skipped','cancelled') then raise exception 'Invalid terminal step state';end if;select * into s from public.orchestration_step_runtime where id=p_runtime_step_id for update;if not found then raise exception 'Step not found';end if;select * into p from public.orchestration_plans where id=s.plan_id;if p.owner_id<>p_actor_id and not public.has_role(p_actor_id,'admin') and not svc then raise exception 'Forbidden';end if;update public.orchestration_step_runtime set status=p_status,result=coalesce(p_result,'{}'),warnings=coalesce(p_warnings,'[]'),errors=coalesce(p_errors,'[]'),completed_at=case when p_status in ('completed','failed','skipped','cancelled') then now() else null end,lease_expires_at=null,updated_at=now() where id=s.id returning * into s;update public.orchestration_steps set status=p_status,result=coalesce(p_result,'{}'),error=case when jsonb_array_length(coalesce(p_errors,'[]'))>0 then p_errors->>0 else null end,completed_at=case when p_status in ('completed','failed','skipped','cancelled') then now() else null end where id=s.orchestration_step_id;select count(*),count(*) filter(where status='completed'),count(*) filter(where status='failed') into total,done,failed from public.orchestration_step_runtime where plan_id=s.plan_id;if failed>0 and exists(select 1 from public.orchestration_step_runtime where plan_id=s.plan_id and critical and status='failed') then update public.orchestration_plans set status='failed',completed_at=now(),updated_at=now() where id=s.plan_id;elsif done=total then update public.orchestration_plans set status='completed',completed_at=now(),updated_at=now() where id=s.plan_id;else update public.orchestration_plans set status=case when exists(select 1 from public.orchestration_step_runtime where plan_id=s.plan_id and status='waiting_approval') then 'awaiting_approval' else 'executing' end,updated_at=now() where id=s.plan_id;end if;return jsonb_build_object('step',to_jsonb(s),'plan',to_jsonb((select op from public.orchestration_plans op where id=s.plan_id)));end;$$;
create or replace function public.request_phase_n_gate(p_runtime_step_id uuid,p_gate_type text,p_reason text,p_actor_id uuid) returns public.orchestration_gates language plpgsql security definer set search_path=public as $$declare s public.orchestration_step_runtime;p public.orchestration_plans;g public.orchestration_gates;svc boolean:=coalesce(auth.role(),'')='service_role';begin if not svc and auth.uid() is distinct from p_actor_id and not public.has_role(p_actor_id,'admin') then raise exception 'Forbidden';end if;select * into s from public.orchestration_step_runtime where id=p_runtime_step_id;select * into p from public.orchestration_plans where id=s.plan_id;if p.owner_id<>p_actor_id and not public.has_role(p_actor_id,'admin') and not svc then raise exception 'Forbidden';end if;if p_gate_type not in ('approval','verification','policy') then raise exception 'Invalid gate type';end if;insert into public.orchestration_gates(plan_id,runtime_step_id,gate_type,reason,requested_by) values(p.id,s.id,p_gate_type,p_reason,p_actor_id) returning * into g;update public.orchestration_step_runtime set status='waiting_approval',updated_at=now() where id=s.id;update public.orchestration_steps set status='waiting_approval' where id=s.orchestration_step_id;update public.orchestration_plans set status='awaiting_approval',updated_at=now() where id=p.id;return g;end;$$;
